// Тарифы исправленной модели. Себестоимость КГУ — плоская, всё включено;
// пуск оплачивается как событие, а не как эквивалентные моточасы.
const KZT_CHP = 22;            // ₸/кВт*ч собственной выработки
const KZT_GRID = 60;           // ₸/кВт*ч закупа из сети
const KZT_START = 15000;       // ₸ за один пуск агрегата
const KZT_CYCLE = 0.5;         // ₸ за кВт*ч разряда, износ ячеек
const SPREAD = KZT_GRID - KZT_CHP;   // 38 ₸/кВт*ч

const nf = (v) => Math.round(v).toLocaleString("ru");
const nf1 = (v) => v.toLocaleString("ru", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const sg = (v) => (v > 0 ? "+" : v < 0 ? "−" : "");

// Строка: [нагрузка, КГУ, заряд, разряд, SoC %, сеть, пуски, агрегатов в работе,
//          сброс] — всё в кВт, кроме отмеченного.
function expand(rows, baseRows, isWeek, gen) {
  return rows.map((r, i) => {
    const [load, chp, ch, dis, soc, grid, starts, uon, spill] = r;
    const b = baseRows[i];
    // Энергетическая часть экономии — гладкая, её и рисуем вуалью.
    const eC = chp * KZT_CHP + grid * KZT_GRID;
    const eB = b[1] * KZT_CHP + b[5] * KZT_GRID;
    const saveE = eB - eC;
    // Эксплуатационная часть — разовые скачки по 15 000 ₸ за пуск плюс износ
    // ячеек. Вуаль от них стала бы рваной, поэтому она идёт только в подсказку.
    const saveS = (b[6] - starts) * KZT_START - dis * KZT_CYCLE;
    const bess = ch > 0 ? ch : -dis;
    // Высота вуали = экономия часа / спред. Тогда её ПЛОЩАДЬ в кВт·ч,
    // умноженная на спред, в точности равна деньгам.
    const h = saveE / SPREAD;
    return {
      i, load, chp, ch, dis, soc, grid, starts, uon, spill, bess,
      gen: gen[i],
      ...Object.fromEntries(gen[i].map((v, j) => [`u${j}`, v])),
      bandPos: h >= 0 ? [load - h, load] : null,
      bandNeg: h < 0 ? [load, load - h] : null,
      saveE, saveS,
      label: isWeek ? `${DN[Math.floor(i / 24)]} ${String(i % 24).padStart(2, "0")}:00`
                    : `${String(i + 1).padStart(2, "0")}:00`,
    };
  });
}

function Tip({ active, payload, showSave, names }) {
  if (!active || !payload || !payload.length) return null;
  const d = payload[0].payload;
  const rows = [
    ["Нагрузка завода", `${nf(d.load)} кВт`, C.ink],
    ["Выработка КГУ", `${nf(d.chp)} кВт`, C.muted],
    ...names.map((n, j) => [`  ${n}`,
      `${nf(d.gen[j])} кВт · ${d.load > 0 ? ((d.gen[j] / d.load) * 100).toFixed(0) : 0}%`,
      C.gen[j % C.gen.length]]),
    d.ch > 0 ? ["Заряд BESS", `+${nf(d.ch)} кВт`, C.charge] : null,
    d.dis > 0 ? ["Разряд BESS", `−${nf(d.dis)} кВт`, C.discharge] : null,
    ["Закуп из сети", `${nf(d.grid)} кВт`, C.muted],
    d.spill > 0 ? ["Сброс", `${nf(d.spill)} кВт`, C.discharge] : null,
    ["Агрегатов в работе", `${d.uon}`, C.muted],
    ["SoC", `${nf1(d.soc)}%`, C.muted],
    d.starts > 0 ? ["Пусков в этот час", `${d.starts}`, C.discharge] : null,
    showSave ? ["Экономия, энергия", `${sg(d.saveE)}${nf(Math.abs(d.saveE))} ₸`,
                d.saveE >= 0 ? C.save : C.discharge] : null,
    showSave && Math.abs(d.saveS) > 0.5
      ? ["Экономия, пуски и цикл", `${sg(d.saveS)}${nf(Math.abs(d.saveS))} ₸`,
         d.saveS >= 0 ? C.save : C.discharge] : null,
  ].filter(Boolean);
  return (
    <div style={{
      background: C.panel, border: `1px solid ${C.rule}`, padding: "10px 12px",
      fontFamily: MONO, fontSize: 12, color: C.ink, minWidth: 230,
    }}>
      <div style={{ fontWeight: 600, marginBottom: 6, letterSpacing: "0.04em" }}>{d.label}</div>
      {rows.map(([k, v, col]) => (
        <div key={k} style={{ display: "flex", justifyContent: "space-between", gap: 16, lineHeight: 1.7 }}>
          <span style={{ color: C.muted }}>{k}</span>
          <span style={{ color: col, fontVariantNumeric: "tabular-nums" }}>{v}</span>
        </div>
      ))}
    </div>
  );
}

function Panel({ cfg, mode, period }) {
  const isWeek = period === "week";
  const cur = cfg[period][mode];
  // База сравнения — сценарий B: то же правило 90%, тот же контроллер, но без
  // накопителя. Так вуаль показывает эффект ИМЕННО батареи, а не разницу
  // двух разных режимов работы парка.
  const bas = cfg[period].B;
  const rows = useMemo(() => expand(cur.rows, bas.rows, isWeek, cur.gen), [cur, bas, isWeek]);
  const showSave = mode === "C";

  const charged = rows.reduce((a, r) => a + r.ch, 0);
  const dischg = rows.reduce((a, r) => a + r.dis, 0);
  const grid = rows.reduce((a, r) => a + r.grid, 0);
  const peak = Math.max(...rows.map((r) => r.grid));
  const idle = rows.filter((r) => r.ch === 0 && r.dis === 0).length;

  // --- Разложение экономии -------------------------------------------------
  // 1. Энергия: собственная выработка по 22 ₸ против закупа по 60 ₸.
  // 2. Эксплуатация: пуски по 15 000 ₸ плюс износ ячеек 0.5 ₸ за кВт·ч разряда.
  // 3. Поправка на SoC: окно не замкнуто по энергии. Оценивается так же, как
  //    в самой модели: по тарифу сети, который этот запас потом заместит.
  const saveEnergy = rows.reduce((a, r) => a + r.saveE, 0);
  const saveOps = rows.reduce((a, r) => a + r.saveS, 0);
  const stCur = rows.reduce((a, r) => a + r.starts, 0);
  const stBas = bas.rows.reduce((a, r) => a + r[6], 0);
  const dSoc = ((rows[rows.length - 1].soc - cur.soc0) / 100) * cfg.cap;
  const socCorr = dSoc * cfg.eta * KZT_GRID;
  const total = saveEnergy + saveOps + socCorr;

  const loadMax = Math.max(...rows.map((r) => Math.max(r.load, r.load - r.saveE / SPREAD)));
  const disMax = Math.max(...rows.map((r) => r.dis), 0);
  const veilLow = Math.min(...rows.map((r) => r.load - r.saveE / SPREAD), 0);
  const yTop = Math.ceil((loadMax * 1.06) / 500) * 500;
  const yBot = Math.min(-Math.max(500, Math.ceil((disMax * 1.25) / 500) * 500),
                        Math.floor((showSave ? veilLow : 0) / 500) * 500);
  const ticks = [];
  for (let v = yBot; v <= yTop; v += 500) ticks.push(v);

  const xTicks = isWeek
    ? [0, 24, 48, 72, 96, 120, 144]
    : rows.filter((r) => r.i % 2 === 0).map((r) => r.i);

  const stats = [
    ["Заряд", `${nf(charged)} кВт·ч`],
    ["Разряд", `${nf(dischg)} кВт·ч`],
    ["Закуп из сети", `${nf(grid)} кВт·ч`],
    ["Пик закупа", `${nf(peak)} кВт`],
    ["Простой BESS", `${idle} из ${rows.length} ч`],
    ["Экономия итого", showSave ? `${sg(total)}${nf(Math.abs(total))} ₸` : "—"],
  ];

  return (
    <section style={{ background: C.panel, border: `1px solid ${C.rule}`, marginBottom: 28 }}>
      <header style={{
        padding: "16px 20px 12px", borderBottom: `1px solid ${C.rule}`,
        display: "flex", flexWrap: "wrap", alignItems: "baseline", gap: 12,
      }}>
        <h2 style={{
          margin: 0, fontFamily: SANS, fontSize: 19, fontWeight: 650,
          letterSpacing: "-0.015em", color: C.ink,
        }}>
          {cfg.label}
        </h2>
        <span style={{ fontFamily: MONO, fontSize: 11.5, color: C.muted, letterSpacing: "0.02em" }}>
          {cfg.units} = {nf(cfg.pchp)} кВт
        </span>
      </header>

      <div style={{ padding: "18px 8px 4px 0" }}>
        <ResponsiveContainer width="100%" height={isWeek ? 420 : 380}>
          <ComposedChart data={rows} margin={{ top: 8, right: 18, left: 8, bottom: 26 }}>
            <CartesianGrid stroke={C.rule} strokeDasharray="2 4" vertical={false} />
            <XAxis
              dataKey="i" tick={{ fill: C.muted, fontSize: 11, fontFamily: MONO }}
              tickLine={false} axisLine={{ stroke: C.rule }}
              ticks={xTicks} interval={0}
              tickFormatter={(v) => (isWeek ? DN[Math.floor(v / 24)] : String(v + 1))}
              label={{ value: isWeek ? "дни недели" : "час суток",
                       position: "insideBottom", offset: -14,
                       fill: C.muted, fontSize: 11.5, fontFamily: MONO }}
            />
            <YAxis
              domain={[yBot, yTop]} ticks={ticks}
              tick={{ fill: C.muted, fontSize: 11, fontFamily: MONO }}
              tickLine={false} axisLine={false} width={54}
              tickFormatter={(v) => v.toLocaleString("ru")}
              label={{ value: "кВт", angle: -90, position: "insideLeft", offset: 10,
                       fill: C.muted, fontSize: 11.5, fontFamily: MONO }}
            />
            <Tooltip content={<Tip showSave={showSave} names={cfg.names} />}
                     cursor={{ fill: "rgba(23,36,47,0.05)" }} />

            {showSave && (
              <Area dataKey="bandPos" isAnimationActive={false} stroke="none"
                    fill={C.save} fillOpacity={0.18} activeDot={false} connectNulls={false} />
            )}
            {showSave && (
              <Area dataKey="bandNeg" isAnimationActive={false} stroke="none"
                    fill={C.discharge} fillOpacity={0.16} activeDot={false} connectNulls={false} />
            )}

            <ReferenceLine y={0} stroke={C.ink} strokeWidth={1} />
            <ReferenceLine
              y={cfg.pchp} stroke={C.ceiling} strokeDasharray="6 4" strokeWidth={1.25}
              label={{ value: `потолок КГУ ${nf(cfg.pchp)} кВт`,
                       position: "insideTopRight", fill: C.ceiling,
                       fontSize: 11, fontFamily: MONO, dy: -6 }}
            />
            {isWeek && [24, 48, 72, 96, 120, 144].map((d) => (
              <ReferenceLine key={d} x={d} stroke={C.rule} strokeWidth={1} />
            ))}

            {cfg.names.map((n, j) => (
              <Bar key={n} dataKey={`u${j}`} stackId="chp" name={n}
                   barSize={isWeek ? 3 : 13} isAnimationActive={false}
                   fill={C.gen[j % C.gen.length]} fillOpacity={0.85} />
            ))}

            <Bar dataKey="bess" barSize={isWeek ? 3 : 13} isAnimationActive={false}>
              {rows.map((r, i) => (
                <Cell key={i} fill={r.bess >= 0 ? C.charge : C.discharge} />
              ))}
            </Bar>

            <Line
              type="linear" dataKey="load" stroke={C.load}
              strokeWidth={isWeek ? 1.1 : 1.6} isAnimationActive={false}
              dot={isWeek ? { r: 1.3, fill: C.load, stroke: "none" }
                          : { r: 3.2, fill: C.panel, stroke: C.load, strokeWidth: 1.6 }}
              activeDot={{ r: 5, fill: C.load, stroke: C.panel, strokeWidth: 2 }}
            />
          </ComposedChart>
        </ResponsiveContainer>
      </div>

      <div style={{ display: "flex", flexWrap: "wrap", borderTop: `1px solid ${C.rule}` }}>
        {stats.map(([k, v], i) => (
          <div key={k} style={{
            flex: "1 1 130px", padding: "12px 16px",
            borderLeft: i === 0 ? "none" : `1px solid ${C.rule}`,
          }}>
            <div style={{ fontFamily: MONO, fontSize: 10.5, color: C.muted,
                          textTransform: "uppercase", letterSpacing: "0.07em" }}>
              {k}
            </div>
            <div style={{ fontFamily: MONO, fontSize: 15,
                          color: k === "Экономия итого" && v !== "—"
                            ? (total >= 0 ? C.save : C.discharge) : C.ink,
                          marginTop: 4, fontVariantNumeric: "tabular-nums" }}>
              {v}
            </div>
          </div>
        ))}
      </div>

      {showSave && (
        <div style={{ borderTop: `1px solid ${C.rule}`, padding: "10px 16px",
                      fontFamily: MONO, fontSize: 11.5, color: C.muted,
                      display: "flex", flexWrap: "wrap", gap: 18 }}>
          <span>энергия <b style={{ color: saveEnergy >= 0 ? C.save : C.discharge,
                                    fontWeight: 500 }}>
            {sg(saveEnergy)}{nf(Math.abs(saveEnergy))} ₸</b></span>
          <span>пуски {stCur} против {stBas} <b style={{
            color: saveOps >= 0 ? C.save : C.discharge, fontWeight: 500 }}>
            {sg(saveOps)}{nf(Math.abs(saveOps))} ₸</b></span>
          <span>поправка на SoC {sg(dSoc)}{nf(Math.abs(dSoc))} кВт·ч <b style={{
            color: socCorr >= 0 ? C.save : C.discharge, fontWeight: 500 }}>
            {sg(socCorr)}{nf(Math.abs(socCorr))} ₸</b></span>
        </div>
      )}
    </section>
  );
}

function Switch({ items, value, onChange }) {
  return (
    <div style={{ display: "flex", gap: 0, border: `1px solid ${C.rule}`, width: "fit-content" }}>
      {items.map(([k, label], i) => (
        <button
          key={k} onClick={() => onChange(k)}
          style={{
            fontFamily: MONO, fontSize: 12, letterSpacing: "0.04em",
            padding: "9px 18px", cursor: "pointer",
            border: "none", borderLeft: i === 0 ? "none" : `1px solid ${C.rule}`,
            background: value === k ? C.ink : C.panel,
            color: value === k ? C.paper : C.muted,
          }}
        >
          {label}
        </button>
      ))}
    </div>
  );
}

const MODE_NAME = { A: "Свободный 50%", B: "Правило 90%", C: "90% + BESS" };

const th = {
  fontFamily: MONO, fontSize: 10.5, color: C.muted, fontWeight: 400,
  textTransform: "uppercase", letterSpacing: "0.06em",
  padding: "7px 9px", textAlign: "right", whiteSpace: "nowrap",
  borderBottom: `1px solid ${C.rule}`,
};
const td = {
  fontFamily: MONO, fontSize: 12, color: C.ink, padding: "5px 9px",
  textAlign: "right", fontVariantNumeric: "tabular-nums", whiteSpace: "nowrap",
};

function Table({ head, rows, foot }) {
  return (
    <div style={{ overflowX: "auto" }}>
      <table style={{ borderCollapse: "collapse", width: "100%", minWidth: 560 }}>
        <thead>
          <tr>{head.map((h, i) => (
            <th key={i} style={{ ...th, textAlign: i === 0 ? "left" : "right" }}>{h}</th>
          ))}</tr>
        </thead>
        <tbody>
          {rows.map((r, i) => (
            <tr key={i} style={{ background: i % 2 ? "rgba(23,36,47,0.022)" : "transparent" }}>
              {r.map((c, j) => {
                // Ячейка может быть строкой или объектом {v, c}: второй вариант
                // нужен, чтобы красить экономию по знаку прямо в таблице.
                const val = c && typeof c === "object" ? c.v : c;
                const col = c && typeof c === "object" ? c.c
                          : (j === 0 ? C.muted : C.ink);
                return (
                  <td key={j} style={{ ...td, textAlign: j === 0 ? "left" : "right",
                                       color: col }}>{val}</td>
                );
              })}
            </tr>
          ))}
          {foot && (
            <tr>{foot.map((c, j) => (
              <td key={j} style={{ ...td, textAlign: j === 0 ? "left" : "right",
                                   borderTop: `1px solid ${C.ink}`, fontWeight: 600 }}>{c}</td>
            ))}</tr>
          )}
        </tbody>
      </table>
    </div>
  );
}

function Sub({ children }) {
  return (
    <h3 style={{ margin: "26px 0 10px", fontFamily: SANS, fontSize: 14.5, fontWeight: 620,
                 letterSpacing: "-0.01em", color: C.ink }}>{children}</h3>
  );
}

// Деньги считаем одним методом на всех трёх горизонтах: собственная выработка,
// закуп из сети, пуски и износ ячеек.
function money(rows) {
  return rows.reduce((a, r) => a + r[1] * KZT_CHP + r[5] * KZT_GRID
                                 + r[6] * KZT_START + r[3] * KZT_CYCLE, 0);
}
function totals(rows) {
  const s = (k) => rows.reduce((a, r) => a + r[k], 0);
  return { load: s(0), chp: s(1), ch: s(2), dis: s(3), grid: s(5),
           starts: s(6), spill: s(8),
           peak: Math.max(...rows.map((r) => r[5])), cost: money(rows) };
}

function dayTable(cfg, md) {
  const d = cfg.day[md];
  const head = ["Час", "Нагрузка", ...cfg.names, "Заряд +", "Разряд −", "Сеть", "SoC %"];
  const rows = d.rows.map((r, i) => [
    String(i + 1), nf(r[0]), ...d.gen[i].map(nf), nf(r[2]),
    r[3] ? "−" + nf(r[3]) : "0", nf(r[5]), nf1(r[4]),
  ]);
  const t = totals(d.rows);
  const gs = cfg.names.map((_, j) => d.gen.reduce((a, g) => a + g[j], 0));
  const foot = ["Итого", nf(t.load), ...gs.map(nf), nf(t.ch),
                "−" + nf(t.dis), nf(t.grid), ""];
  return { head, rows, foot };
}

function weekTable(cfg, md) {
  const d = cfg.week[md];
  const head = ["День", "Нагрузка", ...cfg.names, "Заряд +", "Разряд −", "Сеть",
                "Пик", "Пусков"];
  const rows = DN.map((dn, k) => {
    const seg = d.rows.slice(k * 24, k * 24 + 24);
    const gseg = d.gen.slice(k * 24, k * 24 + 24);
    const t = totals(seg);
    return [dn, nf(t.load),
            ...cfg.names.map((_, j) => nf(gseg.reduce((a, g) => a + g[j], 0))),
            nf(t.ch), "−" + nf(t.dis), nf(t.grid), nf(t.peak), String(t.starts)];
  });
  const t = totals(d.rows);
  const gs = cfg.names.map((_, j) => d.gen.reduce((a, g) => a + g[j], 0));
  const foot = ["Итого", nf(t.load), ...gs.map(nf), nf(t.ch), "−" + nf(t.dis),
                nf(t.grid), nf(t.peak), String(t.starts)];
  return { head, rows, foot };
}

function hourWeekTable(cfg, md) {
  const d = cfg.week[md];
  const head = ["День", "Час", "Нагрузка", ...cfg.names, "Заряд +", "Разряд −",
                "Сеть", "SoC %"];
  const rows = d.rows.map((r, i) => [
    DN[Math.floor(i / 24)], String((i % 24) + 1), nf(r[0]), ...d.gen[i].map(nf),
    nf(r[2]), r[3] ? "−" + nf(r[3]) : "0", nf(r[5]), nf1(r[4]),
  ]);
  return { head, rows };
}

// Сводная таблица на трёх горизонтах. Экономия считается от сценария B —
// то же ограничение, тот же контроллер, но без накопителя.
function summaryTable(cfg, sum) {
  const dw = (per) => {
    const g = (m) => totals(cfg[per][m].rows);
    return { A: g("A"), B: g("B"), C: g("C") };
  };
  const day = dw("day"), week = dw("week");
  const gr = (v) => ({ v: `${sg(v)}${nf(Math.abs(v))}`, c: v >= 0 ? C.save : C.discharge });
  const head = ["Показатель", "A. Свободный 50%", "B. Правило 90%", "C. 90% + BESS"];
  const rows = [];
  const blk = (t, unit, f, fmt = nf) => rows.push([t + (unit ? `, ${unit}` : ""),
    fmt(f(day.A)), fmt(f(day.B)), fmt(f(day.C))]);
  rows.push([{ v: "ТИПИЧНЫЕ СУТКИ", c: C.ink }, "", "", ""]);
  blk("Нагрузка завода", "кВт·ч", (x) => x.load);
  blk("Выработка КГУ", "кВт·ч", (x) => x.chp);
  blk("Заряд BESS", "кВт·ч", (x) => x.ch);
  blk("Разряд BESS", "кВт·ч", (x) => x.dis);
  blk("Закуп из сети", "кВт·ч", (x) => x.grid);
  blk("Пик закупа", "кВт", (x) => x.peak);
  blk("Пусков", "", (x) => x.starts);
  blk("Затраты", "₸", (x) => x.cost);
  rows.push(["Экономия к B, ₸", gr(day.B.cost - day.A.cost), "—",
             gr(day.B.cost - day.C.cost)]);

  rows.push([{ v: "НЕДЕЛЯ", c: C.ink }, "", "", ""]);
  const wb = (t, unit, f) => rows.push([t + (unit ? `, ${unit}` : ""),
    nf(f(week.A)), nf(f(week.B)), nf(f(week.C))]);
  wb("Нагрузка завода", "кВт·ч", (x) => x.load);
  wb("Выработка КГУ", "кВт·ч", (x) => x.chp);
  wb("Заряд BESS", "кВт·ч", (x) => x.ch);
  wb("Разряд BESS", "кВт·ч", (x) => x.dis);
  wb("Закуп из сети", "кВт·ч", (x) => x.grid);
  wb("Пик закупа", "кВт", (x) => x.peak);
  wb("Пусков", "", (x) => x.starts);
  wb("Затраты", "₸", (x) => x.cost);
  rows.push(["Экономия к B, ₸", gr(week.B.cost - week.A.cost), "—",
             gr(week.B.cost - week.C.cost)]);

  rows.push([{ v: "ГОД, 8760 Ч", c: C.ink }, "", "", ""]);
  const yb = (t, unit, f, fmt = nf) => rows.push([t + (unit ? `, ${unit}` : ""),
    fmt(f(sum.A)), fmt(f(sum.B)), fmt(f(sum.C))]);
  yb("Выработка КГУ", "МВт·ч", (x) => x.chp);
  yb("Закуп из сети", "МВт·ч", (x) => x.grid);
  yb("Доля сети", "%", (x) => x.share, nf1);
  yb("Сброс", "МВт·ч", (x) => x.spill);
  yb("Моточасы парка", "", (x) => x.hours);
  yb("Пусков за год", "", (x) => x.starts);
  yb("Полных циклов BESS", "", (x) => x.efc, nf1);
  yb("Топливо и O&M", "₸", (x) => x.chpcost);
  yb("Закуп из сети", "₸", (x) => x.gridcost);
  yb("Пуски", "₸", (x) => x.startcost);
  yb("Износ ячеек", "₸", (x) => x.cyccost);
  yb("Поправка на SoC", "₸", (x) => x.drift);
  yb("ИТОГО затраты", "₸/год", (x) => x.cost);
  rows.push(["Экономия к B, ₸/год", gr(sum.B.cost - sum.A.cost), "—",
             gr(sum.saveB)]);
  rows.push(["Окупаемость к B, лет", "—", "—",
             { v: sum.payB ? nf1(sum.payB) : "нет", c: sum.payB ? C.save : C.discharge }]);
  rows.push(["Экономия к A, ₸/год", "—", gr(sum.A.cost - sum.B.cost), gr(sum.saveA)]);
  rows.push(["Окупаемость к A, лет", "—", "—",
             { v: sum.payA ? nf1(sum.payA) : "нет", c: sum.payA ? C.save : C.discharge }]);
  return { head, rows };
}

function Profiles({ cfg, list }) {
  const head = ["Профиль нагрузки", "Средняя, кВт", "Пик, кВт", "A, ₸/год", "B, ₸/год",
                "C, ₸/год", "Экономия к B", "Окуп., лет"];
  const rows = list.map((p) => [
    p.name, nf(p.mean), nf(p.peak), nf(p.a), nf(p.b), nf(p.cc),
    { v: `${sg(p.sb)}${nf(Math.abs(p.sb))}`, c: p.sb >= 0 ? C.save : C.discharge },
    { v: p.payB ? nf1(p.payB) : "нет", c: p.payB && p.payB <= 10 ? C.save : C.ink },
  ]);
  return (
    <>
      <Sub>Восемь архетипов нагрузки</Sub>
      <p style={{ margin: "0 0 10px", fontFamily: SANS, fontSize: 13.5, color: C.muted,
                  lineHeight: 1.5 }}>
        Один профиль ничего не доказывает. Модель прогоняется по всей семье, и результат
        читается как диапазон, а не как одно число.
      </p>
      <Table head={head} rows={rows} />
    </>
  );
}

function ReportBlock({ cfg, sum, list }) {
  const [md, setMd] = useState("C");
  const [full, setFull] = useState(false);
  const dt = dayTable(cfg, md), wt = weekTable(cfg, md);
  const st = summaryTable(cfg, sum);
  const hw = full ? hourWeekTable(cfg, md) : null;
  return (
    <section style={{ background: C.panel, border: `1px solid ${C.rule}`,
                      padding: "18px 20px 24px", marginBottom: 28 }}>
      <div style={{ display: "flex", flexWrap: "wrap", alignItems: "baseline",
                    gap: 12, marginBottom: 6 }}>
        <h2 style={{ margin: 0, fontFamily: SANS, fontSize: 19, fontWeight: 650,
                     letterSpacing: "-0.015em", color: C.ink }}>
          Отчёт · {cfg.label}
        </h2>
        <span style={{ fontFamily: MONO, fontSize: 11.5, color: C.muted }}>
          {cfg.units} = {nf(cfg.pchp)} кВт · BESS {nf(cfg.cap)} кВт·ч
        </span>
      </div>
      <div style={{ display: "flex", gap: 14, flexWrap: "wrap", margin: "14px 0 4px" }}>
        <Switch items={[["A", MODE_NAME.A], ["B", MODE_NAME.B], ["C", MODE_NAME.C]]}
                value={md} onChange={setMd} />
        <Switch items={[[false, "Сводка по суткам"], [true, "168 часов"]]}
                value={full} onChange={setFull} />
      </div>
      <Sub>Типичные сутки · {cfg.dayDate} · {MODE_NAME[md]}</Sub>
      <Table {...dt} />
      <Sub>Неделя с {cfg.weekDate} · {MODE_NAME[md]}</Sub>
      <Table {...wt} />
      {full && (<><Sub>Неделя, почасовой профиль, 168 часов</Sub><Table {...hw} /></>)}
      <Sub>Сводная таблица</Sub>
      <Table {...st} />
      <Profiles cfg={cfg} list={list} />
    </section>
  );
}

export default function BessProfile() {
  const [mode, setMode] = useState("C");
  const [period, setPeriod] = useState("day");

  const modes = [["A", MODE_NAME.A], ["B", MODE_NAME.B], ["C", MODE_NAME.C]];
  const periods = [["day", "Сутки"], ["week", "7 дней"]];
  const isWeek = period === "week";
  const showSave = mode === "C";

  const kpi = [
    ["Экономия к B", `${sg(SUMMARY.chp2.saveB)}${nf(Math.abs(SUMMARY.chp2.saveB))} ₸/год`,
     SUMMARY.chp2.saveB >= 0 ? C.save : C.discharge],
    ["Окупаемость к B", SUMMARY.chp2.payB ? `${nf1(SUMMARY.chp2.payB)} года` : "нет",
     SUMMARY.chp2.payB ? C.save : C.discharge],
    ["Экономия к A", `${sg(SUMMARY.chp2.saveA)}${nf(Math.abs(SUMMARY.chp2.saveA))} ₸/год`,
     SUMMARY.chp2.saveA >= 0 ? C.save : C.discharge],
    ["Окупаемость к A", SUMMARY.chp2.payA ? `${nf1(SUMMARY.chp2.payA)} года` : "нет",
     SUMMARY.chp2.payA ? C.save : C.discharge],
    ["Артефакт правила 90%", `${nf(SUMMARY.chp2.artifact)} ₸/год`, C.muted],
    ["CAPEX накопителя", `${nf(SUMMARY.chp2.capex)} ₸`, C.ink],
  ];

  return (
    <div style={{ background: C.paper, minHeight: "100%", padding: "28px 20px 36px" }}>
      <div style={{ maxWidth: 900, margin: "0 auto" }}>
        <div style={{ marginBottom: 22 }}>
          <div style={{ fontFamily: MONO, fontSize: 11, color: C.muted,
                        letterSpacing: "0.14em", textTransform: "uppercase" }}>
            {isWeek
              ? `Неделя с ${DATA.chp2.weekDate} · профиль 1 · год 8760 ч`
              : `Типичные сутки · ${DATA.chp2.dayDate} · профиль 1 · год 8760 ч`}
          </div>
          <h1 style={{ margin: "8px 0 0", fontFamily: SANS, fontSize: 27, fontWeight: 680,
                       letterSpacing: "-0.025em", color: C.ink, lineHeight: 1.15 }}>
            Работа накопителя против нагрузки завода
          </h1>
          <p style={{ margin: "10px 0 0", fontFamily: SANS, fontSize: 14.5,
                      color: C.muted, lineHeight: 1.55, maxWidth: 660 }}>
            Точками показана нагрузка завода по часам. Столбцами — вклад каждого
            КГУ (стопкой) и накопитель отдельно: вверх заряд, вниз разряд. Пунктир
            отмечает суммарную мощность КГУ. Вуаль показывает деньги: её высота
            равна экономии часа, делённой на спред 38 ₸/кВт·ч, поэтому площадь
            вуали, умноженная на спред, и есть тенге. Сравнение идёт против
            сценария B — то же правило 90%, тот же контроллер, но без накопителя.
          </p>
        </div>

        <div style={{ display: "flex", flexWrap: "wrap", border: `1px solid ${C.rule}`,
                      background: C.panel, marginBottom: 22 }}>
          {kpi.map(([k, v, col], i) => (
            <div key={k} style={{ flex: "1 1 150px", padding: "13px 16px",
                                  borderLeft: i === 0 ? "none" : `1px solid ${C.rule}` }}>
              <div style={{ fontFamily: MONO, fontSize: 10.5, color: C.muted,
                            textTransform: "uppercase", letterSpacing: "0.07em" }}>{k}</div>
              <div style={{ fontFamily: MONO, fontSize: 15, color: col, marginTop: 4,
                            fontVariantNumeric: "tabular-nums" }}>{v}</div>
            </div>
          ))}
        </div>

        <div style={{ display: "flex", gap: 14, flexWrap: "wrap", marginBottom: 22 }}>
          <Switch items={modes} value={mode} onChange={setMode} />
          <Switch items={periods} value={period} onChange={setPeriod} />
        </div>

        <Panel cfg={DATA.chp2} mode={mode} period={period} />
        <Panel cfg={DATA.chp3} mode={mode} period={period} />

        <div style={{ border: `1px solid ${C.rule}`, background: C.panel,
                      padding: "12px 16px", marginBottom: 22,
                      fontFamily: MONO, fontSize: 11.5, color: C.muted, lineHeight: 1.6 }}>
          <b style={{ color: C.ink, fontWeight: 500 }}>{MODE_NAME.A}</b> — агрегаты
          модулируют от технического минимума 50% без правила 90%; это честная база
          «как есть».{" "}
          <b style={{ color: C.ink, fontWeight: 500 }}>{MODE_NAME.B}</b> — то же
          оборудование под правилом 90%, без накопителя.{" "}
          <b style={{ color: C.ink, fontWeight: 500 }}>{MODE_NAME.C}</b> — то же
          правило плюс накопитель. Состав выбирается по <b style={{ color: C.ink,
          fontWeight: 500 }}>полной стоимости часа</b>, включая пуск: гистерезис
          возникает сам, ручной deadband не нужен. Заряд приходуется на склад по цене
          окна, разряд списывается по себестоимости партии — порог разряда выводится
          из этого, а не задаётся константой.
        </div>

        <ReportBlock cfg={DATA.chp2} sum={SUMMARY.chp2} list={PROFILES.chp2} />
        <ReportBlock cfg={DATA.chp3} sum={SUMMARY.chp3} list={PROFILES.chp3} />

        <div style={{ display: "flex", flexWrap: "wrap", gap: 20, alignItems: "center",
                      fontFamily: MONO, fontSize: 11.5, color: C.muted, marginTop: 4 }}>
          <span style={{ display: "flex", alignItems: "center", gap: 7 }}>
            <span style={{ width: 22, height: 1.6, background: C.load, display: "inline-block" }} />
            нагрузка завода
          </span>
          {DATA.chp3.names.map((n, j) => (
            <span key={n} style={{ display: "flex", alignItems: "center", gap: 7 }}>
              <span style={{ width: 13, height: 13, background: C.gen[j], opacity: 0.85,
                             display: "inline-block" }} />{n}
            </span>
          ))}
          <span style={{ display: "flex", alignItems: "center", gap: 7 }}>
            <span style={{ width: 13, height: 13, background: C.charge, display: "inline-block" }} />
            заряд BESS
          </span>
          <span style={{ display: "flex", alignItems: "center", gap: 7 }}>
            <span style={{ width: 13, height: 13, background: C.discharge, display: "inline-block" }} />
            разряд BESS
          </span>
          {showSave && (
            <span style={{ display: "flex", alignItems: "center", gap: 7 }}>
              <span style={{ width: 13, height: 13, background: C.save, opacity: 0.35,
                             display: "inline-block" }} />
              экономия · площадь × 38 ₸/кВт·ч
            </span>
          )}
        </div>
      </div>
    </div>
  );
}
